select ideas.put_theses($wsj$[{"thesis_key": "rack_power_800vdc_2027", "title": "AI 랙 전력이 800VDC 로 가면 전력의 가치가 소자에서 랙 전원 시스템으로 옮겨간다", "statement": "랙당 전력이 100kW 를 넘어 메가와트급으로 가면 54V 분배는 구리·손실·공간에서 한계에 부딪히고, NVIDIA 는 2027년 Rubin Ultra·Kyber 세대에서 800VDC 랙 전력을 표준으로 밀고 있다. OCP 에서 800VDC 공급망 발표가 시연에서 계약 단계로 넘어갔고(2026-10), Infineon 은 NVIDIA 와 GaN 전력변환 협력을 넓히며 빌라흐에 €1.1bn 300mm GaN 팹을, Wolfspeed 는 200mm SiC 공급 확대를, Infineon–Enphase 는 900V GaN 양방향 스위치(SST 부품)를 확인했다. 이 전환에서 돈은 소자(GaN·SiC)만이 아니라 중전압 AC 를 800VDC 로 바로 바꾸는 반도체 변압기(SST), 800V→50V 변환 모듈, 고전압 DC 차단(SSCB)·버스바·커넥터 같은 '랙 전원 시스템' 으로 흐른다. 시장은 소자사(Infineon·Navitas)는 이미 읽었지만 보호·차단·변환 모듈과 한국 변압기·버스바 고리는 덜 읽었다는 것이 내기다.", "ecosystem": "power", "chain": [{"node": "demand_driver:agentic_inference", "claim": "추론 랙의 전력 밀도가 메가와트급으로 (추론 — 랙당 kW 관측치 필요)", "evidence": []}, {"node": "gen:800vdc", "claim": "OCP 에서 800VDC 공급망 발표가 시연에서 계약 단계로", "evidence": [{"url": "https://news.google.?oc=5", "title": "OCP 800VDC 공급망 발표", "date": "2026-10-24", "kind": "news"}]}, {"node": "bottleneck:conversion", "claim": "800V→50V 중간버스 변환·보호가 새 병목이고 Infineon·NVIDIA 가 GaN 변환 협력을 확대", "evidence": [{"url": "https://semiconductor-today.com/news_items/2026/oct/infineon-211026.shtml", "title": "Infineon–NVIDIA 800VDC GaN", "date": "2026-10-21", "kind": "trade_press"}]}, {"node": "tech:sic", "claim": "공급 반응: Infineon €1.1bn 300mm GaN 팹, Wolfspeed 200mm SiC 공급 확대", "evidence": [{"url": "https://semiconductor-today.com/news_items/2026/oct/infineon-271026.shtml", "title": "Infineon Villach GaN fab", "date": "2026-10-27", "kind": "trade_press"}, {"url": "https://semiconductor-today.com/news_items/2026/oct/wolfspeed-infineon-161026.shtml", "title": "Wolfspeed–Infineon 200mm SiC", "date": "2026-10-16", "kind": "trade_press"}]}, {"node": "component:sscb", "claim": "고전압 DC 차단·SST 부품이 실증 단계 — Power Integrations·Ideal Power SSCB, Infineon–Enphase 900V 양방향 스위치", "evidence": [{"url": "https://semiconductor-today.com/news_items/2026/oct/powerintegrations-161026.shtml", "tit